import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Сохранения и восстановление","description":"","frontmatter":{"pageId":"players/saves-recovery","contentRevision":2},"headers":[],"relativePath":"ru/players/saves-recovery.md","filePath":"ru/players/saves-recovery.md"}'),l={name:"ru/players/saves-recovery.md"};function s(d,e,i,n,p,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="сохранения-и-восстановление" tabindex="-1">Сохранения и восстановление <a class="header-anchor" href="#сохранения-и-восстановление" aria-label="Permalink to &quot;Сохранения и восстановление&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><ol class="flow-diagram" aria-label="Схема процесса"><li><strong>Остановись</strong><span>Не повторяй перевод новым запросом.</span></li><li><strong>Сохрани доказательства</strong><span>Snapshot, upload и outbox остаются на месте.</span></li><li><strong>Войди заново</strong><span>Тот же аккаунт; исходный replay/серверный сейв.</span></li><li><strong>Проверь исход</strong><span>Карта, статус и почта; отказ — администратору.</span></li></ol><p>Канонический сейв хранится на сервере. Дождись завершения обычного сохранения и отправки перед выходом. При обрыве переподключись: неподтверждённые операции повторяются из outbox с прежними идентификаторами, а не создаются заново.</p><p>В 0.8.1 восстановление незавершённых выдач связано с точным снимком сейва. Если игра предлагает восстановление, прочитай выбранную версию и предупреждения. Не загружай произвольный старый локальный сейв, чтобы «вернуть» уже отправленные вещи.</p><p>Если восстановление не завершается, оставь журналы на месте и передай администратору сервер, время, версию сейва и id операции. Администратор может проверить версии и выполнить контролируемый откат.</p><h2 id="save-cycle" tabindex="-1">Как сохраняются отправки и доставки? <a class="header-anchor" href="#save-cycle" aria-label="Permalink to &quot;Как сохраняются отправки и доставки? {#save-cycle}&quot;">​</a></h2><p>Обычная отправка — цепочка: журнал удаления → точный снимок домашней карты → принятие снимка сервером → исходная операция → подтверждение результата. Доставка подтверждается только после снимка, в котором предметы уже получены. Два сохранения на одном тике во время паузы всё равно могут отличаться содержимым.</p><p>При входе сначала восстанавливается незавершённый локальный снимок, затем читается почта. Поэтому не начинай ручной возврат по одному признаку «посылка ещё видна»: сервер может ждать доказательства уже состоявшегося получения. Переподключение повторяет намерение с прежним id, что отличается от нового запроса.</p><p>Нормальный выход в меню даёт игре закончить сохранение. Принудительное завершение процесса не является способом безопасно отменить сделку.</p><h2 id="recover-tree" tabindex="-1">Дерево решений после обрыва, rollback или reset <a class="header-anchor" href="#recover-tree" aria-label="Permalink to &quot;Дерево решений после обрыва, rollback или reset {#recover-tree}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ситуация</th><th>Следующее действие</th><th>Чего не делать</th></tr></thead><tbody><tr><td>Ответ на перевод неизвестен</td><td>Войти тем же аккаунтом, дождаться повтора, проверить результат</td><td>Создавать дубликат перевода</td></tr><tr><td>Снимок старше последней передачи</td><td>Загрузить принятую сервером версию</td><td>Подменять старый файл текущим</td></tr><tr><td>Администратор сделал rollback</td><td>«В главное меню», затем вход заново</td><td>Продолжать писать из отменённой карты</td></tr><tr><td>Колония reset, старый файл отделён</td><td>Загрузить новую серверную колонию/начать заново по правилам</td><td>Загружать <em>.reset-</em>.rws как новую версию</td></tr><tr><td>Недостаточно доказательств для replay</td><td>Сохранить папку и обратиться к админу</td><td>Удалять журналы, чтобы скрыть окно</td></tr></tbody></table><p>Сохрани pending-snapshot.json, upload-*.rws и outbox.json в <code>Saves/Rimlink/&lt;server&gt;_&lt;player&gt;</code>. Вместе с ними передай администратору время, id операции и текст отказа безопасным способом. Эти файлы могут содержать данные колонии; не публикуй их открыто. Rollback меняет SaveWriteEpoch, reset — SaveGeneration; ни то ни другое не отменяет всю уже совершённую серверную экономику.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Никогда не удаляй outbox/журналы восстановления по совету случайного сообщения. Откат меняет временную линию колонии, но не является откатом всей экономики сервера.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./../admins/backup-recovery">Резервные копии и восстановление</a></li><li><a href="./troubleshooting">Проблемы игрока</a></li><li><a href="./economy">Кошелёк, почта и рынок</a></li></ul>',18)])])}const b=t(l,[["render",s]]);export{u as __pageData,b as default};
